def _registro(codigo):
    if not codigo:
        return None
    cod = str(codigo).strip()[:6]
    return MUNICIPIOS.get(cod)


def uf_por_codigo(codigo: str | None) -> str:
    """Converte o código numérico da UF (ex.: '35') na sigla (ex.: 'SP')."""
    if not codigo:
        return "ND"
    return UF_POR_CODIGO.get(str(codigo).strip()[:2], "ND")


def nome_municipio(codigo: str | None) -> str:
    """Nome do município gestor. Códigos '<UF>0000' indicam gestão estadual."""
    if not codigo:
        return "Não informado"
    cod = str(codigo).strip()[:6]
    if cod.endswith("0000"):
        return f"Gestão Estadual {uf_por_codigo(cod)}"
    reg = MUNICIPIOS.get(cod)
    return reg[0] if reg else f"Município {cod}"


def uf_municipio(codigo: str | None) -> str:
    """Sigla da UF a partir do código do município gestor."""
    reg = _registro(codigo)
    return reg[1] if reg else uf_por_codigo(codigo)


def regiao_saude(codigo: str | None) -> str:
    """
    Região intermediária do IBGE usada como proxy da região de saúde.

    O SIH não traz a região de saúde diretamente; a região intermediária
    oferece um agrupamento territorial equivalente para leitura regional.
    """
    if not codigo:
        return "Não informado"
    cod = str(codigo).strip()[:6]
    if cod.endswith("0000"):
        return f"Gestão Estadual {uf_por_codigo(cod)}"
    reg = MUNICIPIOS.get(cod)
    if not reg or not reg[2]:
        return "Não informado"
    return f"{reg[2]} ({reg[1]})"


def coordenadas(codigo: str | None):
    """Par (latitude, longitude) da sede municipal, ou None."""
    reg = _registro(codigo)
    return reg[3] if reg else None
